namespace Fanex.Age.UI.TotalBets
{

    public partial class HTFT_Page : TotalBets_Page
    {
        #region Override

        public override void RenderContent(HtmlTextWriter writer)
        {
            DataTable HTFTList = View as DataTable;

            HTFT_Template tpl = new HTFT_Template();

            tpl.Contents.HTFTContents.Clear();
            if (HTFTList.Rows.Count > 0)
            {
                tpl.Contents.NotFoundContent.Hide();

                HTFT_Contents_HTFTContents_Block block = new HTFT_Contents_HTFTContents_Block();
                int rowIndex = 1;
                for (int i = 0; i < HTFTList.Rows.Count; i++)
                {
                    DataRow dr = HTFTList.Rows[i];

                    if (HTFTList.Columns.Contains("closed") && Convert.ToInt32(dr["closed"]) != 0)
                    {
                        block.ColorClass = Fanex.Age.UI.Common.RowBgClosed;
                    }
                    else
                    {
                        block.ColorClass = (rowIndex % 2) == 0 ? Fanex.Age.UI.Common.RowBgEven : Fanex.Age.UI.Common.RowBgOdd;
                    }
                    block.ColorOver = Fanex.Age.UI.Common.RowBgOver;
                    block.NoValue = rowIndex.ToString();
                    block.HomeValue = Sunplus.Agent.Model.BL.Cache.CacheRef.GetTeamName(dr["homeid"]) + ((bool)dr["isNeutral"] ? Resources.Lang.IsNeutral : string.Empty);
                    block.MatchId = dr["matchid"].ToString();
                    block.BetType = Fanex.Age.UI.Common.BetListByBetTypeMatch;
                    block.AwayValue = Sunplus.Agent.Model.BL.Cache.CacheRef.GetTeamName(dr["awayid"]);
                    block.HHValue = PositiveNumberRoundColor(dr["totalHH"]);
                    block.HDValue = PositiveNumberRoundColor(dr["totalHD"]);
                    block.HAValue = PositiveNumberRoundColor(dr["totalHA"]);
                    block.DHValue = PositiveNumberRoundColor(dr["totalDH"]);
                    block.DDValue = PositiveNumberRoundColor(dr["totalDD"]);
                    block.DAValue = PositiveNumberRoundColor(dr["totalDA"]);
                    block.AHValue = PositiveNumberRoundColor(dr["totalAH"]);
                    block.ADValue = PositiveNumberRoundColor(dr["totalAD"]);
                    block.AAValue = PositiveNumberRoundColor(dr["totalAA"]);

                    tpl.Contents.HTFTContents.Append(block);
                    rowIndex++;
                }
            }

            if (_fullMode)
            {
                writer.Write(tpl);
            }
            else
            {
                writer.Write(tpl.Contents);
            }   
        }
        
        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return _TotalBetsBO.GetHTFT();
        }
        #endregion

        #region Utility

        /// <summary>
        /// Round color for positive number
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        private string PositiveNumberRoundColor(object number)
        {
            decimal num = Convert.ToDecimal(number);
            return (num > 0) ? "<font color='red'>" + Formater.FormatNumber2(num, CurrentUserSession.Language) + "</font>" : Formater.FormatNumber2(num, CurrentUserSession.Language);
        }
        #endregion
    }

}
